// EMBEDDING — 1-to-few (order with its items)
// Good: items belong only to this order, always loaded together
{
  _id: ObjectId(),
  orderId: 'ORD-001',
  customerId: ObjectId('...'),
  items: [                    // embedded array — OK for small, bounded arrays
    { sku: 'ABC', qty: 2, price: 999 },
    { sku: 'XYZ', qty: 1, price: 299 }
  ],
  total: 2297,
  status: 'confirmed'
}

// REFERENCING — 1-to-many (user with their orders)
// Bad to embed: a user could have thousands of orders over time
{
  _id: ObjectId(),
  email: 'alice@example.com',
  name: 'Alice'
  // orders: [...] — DON'T embed, can grow unboundedly!
  // Instead, store userId in each order document
}

// Orders collection — reference back to user
{
  _id: ObjectId(),
  userId: ObjectId('...'),  // reference to users collection
  total: 2297,
  placedAt: new Date()
}

// Pure reference — requires $lookup to get author name
{
  _id: ObjectId(),
  title: 'MongoDB Schema Design',
  authorId: ObjectId('...')  // must $lookup users collection
}

// Extended reference — author name copied in for fast reads
{
  _id: ObjectId(),
  title: 'MongoDB Schema Design',
  author: {
    _id: ObjectId('...'),   // keep _id for linking
    name: 'Alice Sharma',   // copied from users — no join needed!
    avatar: '/avatars/alice.jpg'
  }
  // Note: if Alice changes her name, you must update this too
}

// Instead of computing average rating on every page load:
// SELECT AVG(rating) FROM reviews WHERE productId = '...'

// Store the computed values in the product document:
{
  _id: ObjectId(),
  name: 'Wireless Headphones',
  price: 2499,
  // Pre-computed aggregates — updated whenever a review is added
  ratings: {
    average: 4.3,
    count: 128,
    sum: 550.4  // kept for recalculation accuracy
  }
}

// When a new review is added, update atomically:
await products.updateOne(
  { _id: productId },
  {
    $inc: { 'ratings.count': 1, 'ratings.sum': newRating },
    $set: { 'ratings.average': (currentSum + newRating) / (currentCount + 1) }
  }
);

// BAD: one document per measurement — millions of tiny documents
{ sensorId: 'S1', timestamp: ISODate('2026-11-12T10:00:01Z'), temp: 22.5 }
{ sensorId: 'S1', timestamp: ISODate('2026-11-12T10:00:02Z'), temp: 22.6 }
// ... millions more

// GOOD: bucket pattern — one document per hour per sensor
{
  sensorId: 'S1',
  date: ISODate('2026-11-12T10:00:00Z'),  // hour bucket start
  count: 3600,
  measurements: [
    { ts: ISODate('2026-11-12T10:00:01Z'), temp: 22.5 },
    { ts: ISODate('2026-11-12T10:00:02Z'), temp: 22.6 },
    // up to 3600 entries per document
  ],
  stats: { min: 22.1, max: 23.4, avg: 22.7 }  // computed
}
// Result: 24 documents per sensor per day instead of 86,400!
